38. async function holdKey(
39.   page: Page,
40.   key: string,
41.   duration = 180,
42. ): Promise<void> {
43.   await page.keyboard.down(key);
44.   await page.waitForTimeout(duration);
45.   await page.keyboard.up(key);
46.   await page.waitForTimeout(120);
47. }
48. 
49. async function clickGame(
50.   page: Page,
51.   gameX: number,
52.   gameY: number,
53. ): Promise<void> {
54.   const canvas = page.locator("#game-container canvas");
55.   await expect(canvas).toBeVisible();
56.   const bounds = await canvas.boundingBox();
57.   if (!bounds) throw new Error("Game canvas has no rendered bounds");
58.   await page.mouse.click(
59.     bounds.x + (gameX / GAME_WIDTH) * bounds.width,
60.     bounds.y + (gameY / GAME_HEIGHT) * bounds.height,
61.   );
62. }
