64. async function waitForState(page: Page, text: string): Promise<void> {
65.   await expect(page.locator("#debug-state")).toContainText(text);
66. }
67. 
68. async function enableDebug(page: Page): Promise<void> {
69.   const checkbox = page.locator("#debug-checkbox");
70.   if (!await checkbox.isChecked()) await checkbox.check();
71.   await expect(page.locator("#debug-panel")).toBeVisible();
72. }
73. 
74. async function submitDebug(page: Page, command: string): Promise<void> {
75.   const input = page.locator("#debug-cmd");
76.   await input.fill(command);
77.   await input.press("Enter");
78.   await input.blur();
79. }
