81. async function readSave(page: Page): Promise<BrowserSave> {
82.   return page.evaluate((saveKey) => {
83.     const raw = localStorage.getItem(saveKey);
84.     if (!raw) throw new Error(`Missing localStorage save: ${saveKey}`);
85.     return JSON.parse(raw) as BrowserSave;
86.   }, SAVE_KEY);
87. }
