95. async function enterCurrentTown(
96.   page: Page,
97.   expectedCityState: string,
98. ): Promise<void> {
99.   for (let attempt = 0; attempt < 5; attempt += 1) {
100.     await holdKey(page, "Space", 300);
101.     const state = await page.locator("#debug-state").textContent() ?? "";
102.     if (state.includes(expectedCityState)) return;
103.   }
104.   throw new Error(`Timed out entering town: ${expectedCityState}`);
105. }
