107. async function advanceGenericCutscene(page: Page): Promise<void> {
108.   await page.waitForTimeout(420);
109.   await holdKey(page, "Enter");
110.   await page.waitForTimeout(420);
111. }
112. 
113. async function drainGenericCutscenesUntil(
114.   page: Page,
115.   destination: string,
116. ): Promise<void> {
117.   for (let attempt = 0; attempt < 30; attempt += 1) {
118.     const state = await page.locator("#debug-state").textContent() ?? "";
119.     if (state.includes(destination)) return;
120.     if (state.includes("CUTSCENE")) {
121.       await advanceGenericCutscene(page);
122.     } else {
123.       await page.waitForTimeout(150);
124.     }
125.   }
126.   throw new Error(`Timed out draining cutscenes to ${destination}`);
127. }
